/*
 * sprite_frame.h: sprite frames as lists of hardware sprites ("parts").
 *
 * A hardware sprite is at most 63 pixels wide, so wide frames (dragons, the
 * demon, text) are made of several parts. The frame table itself
 * (assets/frames.h) is generated by assets/gen-sprites.py.
 */

#ifndef SPRITE_FRAME_H
#define SPRITE_FRAME_H

struct sprite_part {
	unsigned short addr;	/* video memory word address */
	unsigned char w, h;	/* size in pixels (w multiple of 4, <= 60) */
	short dx, dy;		/* offset from the frame origin */
};

struct sprite_frame {
	unsigned char n;		/* number of parts */
	const struct sprite_part* parts;
	short hx, hy, hw, hh;		/* hit box, relative to the frame origin */
};

#endif
